create or replace function public.sheet_sync_apply(p jsonb) returns jsonb language plpgsql security definer set search_path to 'public' as $fn$ declare v_run timestamptz := clock_timestamp(); v_batch text := 'sheet_sync_' || to_char(clock_timestamp() at time zone 'America/New_York', 'YYYY-MM-DD'); r jsonb; v_id bigint; v_job uuid; v_row record; v_cnt int; v_key text; v_pid text; v_date date; v_total numeric; v_cancel boolean; v_name text; v_product text; v_addr text; v_contract numeric; v_m text[]; v_trade text; v_rep boolean; v_names text[]; c_new int := 0; c_upd int := 0; c_removed int := 0; c_linked int := 0; c_created int := 0; c_lost int := 0; c_dates int := 0; c_trades int := 0; c_hold int := 0; c_unhold int := 0; c_lost_tab int := 0; c_clog_new int := 0; c_clog_upd int := 0; c_clog_removed int := 0; c_issues int := 0; v_match jsonb; begin if auth.uid() is not null and not public.is_admin() then raise exception 'office only' using errcode = '42501'; end if; if jsonb_typeof(p -> 'sales') = 'array' then for r in select * from jsonb_array_elements(p -> 'sales') loop v_name := nullif(btrim(r ->> 'name'), ''); continue when v_name is null; v_pid := nullif(regexp_replace(coalesce(r ->> 'pid', ''), '\D', '', 'g'), ''); v_date := nullif(r ->> 'sales_date', '')::date; v_total := nullif(r ->> 'total', '')::numeric; v_cancel := coalesce((r ->> 'cancelled')::boolean, false); v_product := nullif(btrim(r ->> 'product'), ''); v_key := public.sheet_row_key(v_name, v_pid, v_date); v_id := null; select s.id into v_id from sales_log_rows s where s.tab = 'Sales' and s.row_key = v_key and (s.last_seen_at is null or s.last_seen_at < v_run) order by s.removed_at nulls first, s.id limit 1; if v_id is null then select s.id into v_id from sales_log_rows s where s.tab = 'Sales' and (s.last_seen_at is null or s.last_seen_at < v_run) and s.ghl_project_id is not distinct from v_pid and s.sales_date is not distinct from v_date and (s.total is not distinct from v_total or (s.cancelled and v_cancel)) order by s.removed_at nulls first, s.id limit 1; end if; if v_id is null then insert into sales_log_rows(source, tab, sheet_row, customer, ghl_project_id, sales_date, product, total, phone, city, cancelled, row_key, last_seen_at) values ('live', 'Sales', nullif(r ->> 'row', '')::int, v_name, v_pid, v_date, v_product, v_total, nullif(r ->> 'phone', ''), nullif(r ->> 'city', ''), v_cancel, v_key, v_run); c_new := c_new + 1; else update sales_log_rows s set sheet_row = nullif(r ->> 'row', '')::int, customer = v_name, ghl_project_id = v_pid, sales_date = v_date, product = v_product, total = v_total, phone = coalesce(nullif(r ->> 'phone', ''), s.phone), city = coalesce(nullif(r ->> 'city', ''), s.city), cancelled = v_cancel, row_key = v_key, last_seen_at = v_run, removed_at = null where s.id = v_id; c_upd := c_upd + 1; end if; end loop; if jsonb_array_length(p -> 'sales') >= 50 then update sales_log_rows s set removed_at = v_run where s.tab = 'Sales' and s.removed_at is null and (s.last_seen_at is null or s.last_seen_at < v_run); get diagnostics c_removed = row_count; end if; for v_row in select s.* from sales_log_rows s where s.tab = 'Sales' and s.last_seen_at = v_run and s.job_id is null order by s.cancelled, s.sales_date nulls last, s.id loop v_job := null; if length(coalesce(v_row.ghl_project_id, '')) >= 6 then select j.id into v_job from jobs j where public.norm_display_id(j.ghl_project_display_id) = v_row.ghl_project_id and not exists (select 1 from sales_log_rows o where o.tab = 'Sales' and o.removed_at is null and o.job_id = j.id) order by (abs(j.contract_amount - coalesce(v_row.total, -1)) < 1) desc, ((j.ghl_status in ('lost', 'abandoned')) = v_row.cancelled) desc, j.number limit 1; end if; if v_job is null and v_row.total is not null then select j.id into v_job from jobs j where public.norm_person(j.customer_name) = public.norm_person(v_row.customer) and abs(j.contract_amount - v_row.total) <= greatest(1, 0.02 * v_row.total) and not exists (select 1 from sales_log_rows o where o.tab = 'Sales' and o.removed_at is null and o.job_id = j.id) order by j.number limit 1; end if; if v_job is not null then update sales_log_rows set job_id = v_job, match_method = 'live' where id = v_row.id; c_linked := c_linked + 1; insert into reconciliation_changes(batch, job_id, job_number, kind, new_text, note) select v_batch, j.id, j.number, 'link', 'Sales row ' || coalesce(v_row.sheet_row::text, '?'), 'Sales tab row ' || coalesce(v_row.sheet_row::text, '?') || ' ' || v_row.customer || ' linked by the sheet sync' from jobs j where j.id = v_job; else v_m := public.match_trades(v_row.product); v_rep := coalesce(public.match_is_repair(v_row.product), false); v_trade := case when cardinality(v_m) = 0 then 'other' when cardinality(v_m) = 1 then v_m[1] else 'combo' end; if cardinality(v_m) = 0 then v_m := array['other']; end if; insert into jobs(customer_name, customer_phone, customer_address, trade, trades, is_repair, stage, contract_amount, contract_signed_date, ghl_project_display_id, ghl_status, status_locked, notes, trade_locked, trade_source) values (v_row.customer, coalesce(v_row.phone, ''), coalesce(v_row.city, ''), v_trade, v_m, v_rep, 'signed', coalesce(v_row.total, 0), v_row.sales_date, case when length(coalesce(v_row.ghl_project_id, '')) >= 6 then v_row.ghl_project_id end, case when v_row.cancelled then 'lost' else 'open' end, v_row.cancelled, 'Created by the sheet sync from the 2026 Sales Log, Sales tab row ' || coalesce(v_row.sheet_row::text, '?') || case when v_row.cancelled then ' (cancelled).' else '.' end, v_row.product is not null, 'sales_log') returning id into v_job; update sales_log_rows set job_id = v_job, match_method = 'created' where id = v_row.id; c_created := c_created + 1; insert into reconciliation_changes(batch, job_id, job_number, kind, new_amount, new_text, note) select v_batch, j.id, j.number, 'job_created', j.contract_amount, j.ghl_status, j.notes from jobs j where j.id = v_job; end if; end loop; for v_row in select s.id sid, s.job_id, s.sheet_row, s.cancelled, s.sales_date, s.product, j.number jnum, j.ghl_status jstatus, j.contract_signed_date jsigned, j.trade jtrade, j.trades jtrades, j.is_repair jrep, j.trade_source jsrc from sales_log_rows s join jobs j on j.id = s.job_id where s.tab = 'Sales' and s.last_seen_at = v_run loop if v_row.cancelled and v_row.jstatus not in ('lost', 'abandoned') and not exists (select 1 from sales_log_rows o where o.job_id = v_row.job_id and o.tab = 'Sales' and o.removed_at is null and not o.cancelled) then update jobs set ghl_status = 'lost', status_locked = true where id = v_row.job_id; c_lost := c_lost + 1; insert into reconciliation_changes(batch, job_id, job_number, kind, old_text, new_text, note) values (v_batch, v_row.job_id, v_row.jnum, 'status', v_row.jstatus, 'lost', 'Cancelled on the Sales tab, row ' || coalesce(v_row.sheet_row::text, '?')); end if; if not v_row.cancelled and v_row.sales_date >= date '2026-01-01' and v_row.jsigned is distinct from v_row.sales_date and v_row.sales_date = (select min(o.sales_date) from sales_log_rows o where o.job_id = v_row.job_id and o.tab = 'Sales' and o.removed_at is null and not o.cancelled) then update jobs set contract_signed_date = v_row.sales_date where id = v_row.job_id; c_dates := c_dates + 1; insert into reconciliation_changes(batch, job_id, job_number, kind, old_date, new_date, note) values (v_batch, v_row.job_id, v_row.jnum, 'signed_date', v_row.jsigned, v_row.sales_date, 'Sales date from the Sales tab, row ' || coalesce(v_row.sheet_row::text, '?')); end if; if not v_row.cancelled and v_row.product is not null and coalesce(v_row.jsrc, 'ghl') <> 'tradedesk' then v_m := public.match_trades(v_row.product); v_rep := coalesce(public.match_is_repair(v_row.product), false); if (cardinality(v_m) > 0 and not (v_m <@ coalesce(v_row.jtrades, '{}'))) or (v_rep and not v_row.jrep) then select array_agg(distinct k order by k) into v_m from unnest(v_m || coalesce(v_row.jtrades, '{}')) k; if cardinality(v_m) > 1 then v_m := array_remove(v_m, 'other'); end if; v_trade := case when cardinality(v_m) = 1 then v_m[1] else 'combo' end; update jobs set trade = v_trade, trades = v_m, is_repair = (v_rep or v_row.jrep), trade_locked = true, trade_source = 'sales_log' where id = v_row.job_id; c_trades := c_trades + 1; insert into reconciliation_changes(batch, job_id, job_number, kind, old_text, new_text, note) values (v_batch, v_row.job_id, v_row.jnum, 'trade', v_row.jtrade || ' ' || array_to_string(coalesce(v_row.jtrades, '{}'), '+'), v_trade || ' ' || array_to_string(v_m, '+'), 'Product on the Sales tab: ' || v_row.product); end if; end if; end loop; insert into sheet_sync_issues(kind, sheet_ref, job_id, sheet_value, td_value, detail, first_seen, last_seen) select 'contract', 'job:' || j.id, j.id, t.sheet_total, j.contract_amount, 'JOB-' || lpad(j.number::text, 4, '0') || ' ' || j.customer_name || ': Sales tab row(s) ' || t.rows_ || ' total ' || to_char(t.sheet_total, 'FM$999,999,990.00') || ', TradeDesk contract ' || to_char(j.contract_amount, 'FM$999,999,990.00'), v_run, v_run from (select o.job_id, sum(coalesce(o.total, 0)) sheet_total, string_agg(o.sheet_row::text, ', ' order by o.sheet_row) rows_ from sales_log_rows o where o.tab = 'Sales' and o.removed_at is null and not o.cancelled and o.job_id is not null group by o.job_id) t join jobs j on j.id = t.job_id where abs(j.contract_amount - t.sheet_total) >= 1 and j.ghl_status not in ('lost', 'abandoned') on conflict (kind, sheet_ref) do update set sheet_value = excluded.sheet_value, td_value = excluded.td_value, detail = excluded.detail, last_seen = excluded.last_seen, resolved_at = null; update sheet_sync_issues set resolved_at = v_run where kind = 'contract' and resolved_at is null and last_seen < v_run; insert into sheet_sync_issues(kind, sheet_ref, job_id, detail, first_seen, last_seen) select 'sales_row_removed', 'row:' || s.id, s.job_id, 'Sales tab row for ' || s.customer || coalesce(' (' || s.sales_date || ')', '') || ' is no longer on the sheet; its TradeDesk job was left as is', v_run, v_run from sales_log_rows s where s.tab = 'Sales' and s.removed_at is not null and s.job_id is not null on conflict (kind, sheet_ref) do update set last_seen = excluded.last_seen, resolved_at = null; update sheet_sync_issues set resolved_at = v_run where kind = 'sales_row_removed' and resolved_at is null and last_seen < v_run; end if; if jsonb_typeof(p -> 'hold') = 'array' then v_names := array(select distinct public.norm_person(e ->> 'name') from jsonb_array_elements(p -> 'hold') e where nullif(btrim(e ->> 'name'), '') is not null); foreach v_name in array v_names loop select count(*) into v_cnt from jobs j where public.norm_person(j.customer_name) = v_name and j.ghl_status not in ('lost', 'abandoned'); if v_cnt = 1 then select j.id into v_job from jobs j where public.norm_person(j.customer_name) = v_name and j.ghl_status not in ('lost', 'abandoned'); if exists (select 1 from jobs j where j.id = v_job and (j.flag is distinct from 'on_hold' or not j.status_locked)) then update jobs set flag = 'on_hold', status_locked = true where id = v_job; c_hold := c_hold + 1; insert into reconciliation_changes(batch, job_id, job_number, kind, new_text, note) select v_batch, j.id, j.number, 'flag', 'on_hold', 'On the Hold tab' from jobs j where j.id = v_job; end if; update sheet_sync_issues set resolved_at = v_run where kind = 'hold_unmatched' and sheet_ref = 'hold:' || v_name and resolved_at is null; else insert into sheet_sync_issues(kind, sheet_ref, detail, first_seen, last_seen) values ('hold_unmatched', 'hold:' || v_name, 'Hold tab name "' || v_name || '" matches ' || v_cnt || ' open TradeDesk jobs, so it was not marked', v_run, v_run) on conflict (kind, sheet_ref) do update set detail = excluded.detail, last_seen = excluded.last_seen, resolved_at = null; c_issues := c_issues + 1; end if; end loop; for v_row in select j.id, j.number from jobs j where j.flag = 'on_hold' and j.status_locked and j.ghl_status not in ('lost', 'abandoned') and public.norm_person(j.customer_name) <> all (v_names) loop update jobs set flag = null, status_locked = false where id = v_row.id; c_unhold := c_unhold + 1; insert into reconciliation_changes(batch, job_id, job_number, kind, old_text, new_text, note) values (v_batch, v_row.id, v_row.number, 'flag', 'on_hold', null, 'No longer on the Hold tab'); end loop; update sheet_sync_issues set resolved_at = v_run where kind = 'hold_unmatched' and resolved_at is null and last_seen < v_run; end if; if jsonb_typeof(p -> 'lost') = 'array' then for v_row in select distinct on (j.id) j.id, j.number, j.ghl_status, e ->> 'tab' tab from jsonb_array_elements(p -> 'lost') e join jobs j on public.norm_person(j.customer_name) = public.norm_person(e ->> 'name') where nullif(btrim(e ->> 'name'), '') is not null and j.ghl_status not in ('lost', 'abandoned') and not exists (select 1 from sales_log_rows o where o.job_id = j.id and o.tab = 'Sales' and o.removed_at is null and not o.cancelled) loop update jobs set ghl_status = 'lost', status_locked = true where id = v_row.id; c_lost_tab := c_lost_tab + 1; insert into reconciliation_changes(batch, job_id, job_number, kind, old_text, new_text, note) values (v_batch, v_row.id, v_row.number, 'status', v_row.ghl_status, 'lost', 'On the ' || coalesce(v_row.tab, 'Lost') || ' tab'); end loop; end if; if jsonb_typeof(p -> 'completion') = 'array' then for r in select * from jsonb_array_elements(p -> 'completion') loop v_name := nullif(btrim(r ->> 'customer'), ''); v_addr := nullif(btrim(r ->> 'address'), ''); continue when v_name is null and v_addr is null; v_contract := nullif(r ->> 'contract', '')::numeric; v_key := public.clog_row_key(v_name, v_addr, v_contract); v_id := null; select c.id into v_id from completion_log_rows c where c.row_key = v_key and (c.last_seen_at is null or c.last_seen_at < v_run) order by c.removed_at nulls first, c.id limit 1; if v_id is null then select c.id into v_id from completion_log_rows c where public.norm_person(c.customer) = public.norm_person(v_name) and public.address_key(c.address) is not distinct from public.address_key(v_addr) and (c.last_seen_at is null or c.last_seen_at < v_run) order by c.removed_at nulls first, abs(coalesce(c.contract_amount, 0) - coalesce(v_contract, 0)), c.id limit 1; end if; if v_id is null then insert into completion_log_rows(source, sheet_row, section, customer, address, projects, contract_amount, amount_collected, date_started, date_completed, date_collected, raw_dates, project_manager, installer, permit_no, notes, match_status, row_key, last_seen_at) values ('live', nullif(r ->> 'row', '')::int, r ->> 'section', v_name, v_addr, nullif(r ->> 'projects', ''), v_contract, nullif(r ->> 'collected', '')::numeric, nullif(r ->> 'date_started', '')::date, nullif(r ->> 'date_completed', '')::date, nullif(r ->> 'date_collected', '')::date, r -> 'raw_dates', nullif(r ->> 'pm', ''), nullif(r ->> 'installer', ''), nullif(r ->> 'permit', ''), nullif(r ->> 'notes', ''), 'unmatched', v_key, v_run); c_clog_new := c_clog_new + 1; else update completion_log_rows c set sheet_row = nullif(r ->> 'row', '')::int, section = r ->> 'section', customer = v_name, address = v_addr, projects = nullif(r ->> 'projects', ''), contract_amount = v_contract, amount_collected = nullif(r ->> 'collected', '')::numeric, date_started = nullif(r ->> 'date_started', '')::date, date_completed = nullif(r ->> 'date_completed', '')::date, date_collected = nullif(r ->> 'date_collected', '')::date, raw_dates = r -> 'raw_dates', project_manager = nullif(r ->> 'pm', ''), installer = nullif(r ->> 'installer', ''), permit_no = nullif(r ->> 'permit', ''), notes = nullif(r ->> 'notes', ''), row_key = v_key, last_seen_at = v_run, updated_at = now(), match_status = case when c.match_status = 'removed' then (case when c.job_id is not null then 'matched' else 'unmatched' end) else c.match_status end, removed_at = null where c.id = v_id; c_clog_upd := c_clog_upd + 1; end if; end loop; if jsonb_array_length(p -> 'completion') >= 50 then update completion_log_rows c set removed_at = v_run, match_status = case when c.match_status in ('matched', 'manual') then 'removed' else c.match_status end where c.removed_at is null and (c.last_seen_at is null or c.last_seen_at < v_run) and c.match_status <> 'ignored'; get diagnostics c_clog_removed = row_count; end if; v_match := public.match_completion_log_rows(); end if; r := jsonb_build_object( 'sales', jsonb_build_object('rows_new', c_new, 'rows_updated', c_upd, 'rows_removed', c_removed, 'linked', c_linked, 'jobs_created', c_created, 'marked_lost', c_lost, 'signed_dates', c_dates, 'trades', c_trades), 'hold', jsonb_build_object('marked', c_hold, 'released', c_unhold, 'unmatched', c_issues), 'lost_tabs', jsonb_build_object('marked_lost', c_lost_tab), 'completion', jsonb_build_object('rows_new', c_clog_new, 'rows_updated', c_clog_upd, 'rows_removed', c_clog_removed, 'matcher', v_match), 'open_issues', (select count(*) from sheet_sync_issues where resolved_at is null)); insert into sheet_sync_runs(reason, summary, ok) values (p ->> 'reason', r, true); return r; end $fn$;;
